CREATE TABLE public.lodging (
    id integer NOT NULL,
    name text NOT NULL,
    type text NOT NULL,
    state text NOT NULL,
    state_abbr text NOT NULL,
    city text NOT NULL,
    price_range text NOT NULL,
    price_per_night_min integer,
    price_per_night_max integer,
    proximity_to_water text NOT NULL,
    amenities text[] DEFAULT '{}'::text[],
    booking_url text,
    rating numeric(2,1) DEFAULT 0,
    review_count integer DEFAULT 0,
    description text,
    phone text,
    pet_friendly boolean DEFAULT false,
    seasonal boolean DEFAULT false,
    season_open text,
    season_close text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT lodging_price_range_check CHECK ((price_range = ANY (ARRAY['$'::text, '$$'::text, '$$$'::text, '$$$$'::text]))),
    CONSTRAINT lodging_type_check CHECK ((type = ANY (ARRAY['hotel'::text, 'cabin'::text, 'campground'::text, 'lodge'::text, 'resort'::text, 'rv_park'::text])))
);

CREATE SEQUENCE public.lodging_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.lodging_id_seq OWNED BY public.lodging.id;


ALTER TABLE ONLY public.lodging ALTER COLUMN id SET DEFAULT nextval('public.lodging_id_seq'::regclass);

ALTER TABLE ONLY public.lodging ADD CONSTRAINT lodging_pkey PRIMARY KEY (id);

SELECT setval('public.lodging_id_seq', COALESCE(MAX(id), 1), MAX(id) IS NOT NULL) FROM public.lodging;